@layer base {
  *, ::after, ::before, ::backdrop { box-sizing: border-box; border: 0px solid; margin: 0px; padding: 0px; }
  ::file-selector-button { box-sizing: border-box; border: 0px solid; margin: 0px; padding: 0px; }
  html, :host { text-size-adjust: 100%; tab-size: 4; line-height: 1.5; font-family: var(--default-font-family,ui-sans-serif,system-ui,sans-serif,"Apple Color Emoji","Segoe UI Emoji","Segoe UI Symbol","Noto Color Emoji"); font-feature-settings: var(--default-font-feature-setting

@layer utilities {
  .pointer-events-auto { pointer-events: auto; }
  .pointer-events-none { pointer-events: none; }
  .collapse { visibility: collapse; }
  .invisible { visibility: hidden; }
  .visible { visibility: visible; }
  .example { margin-block: calc(var(--spacing)*4); border-radius: var(--radius-lg); border-style: var(--tw-border-style); background-color: var(--color-gray-100); padding: calc(var(--spacing)*4); border-width: 1px; justify-content: center; align-items: center; display: fl

@keyframes crt-monitor-in { 
  0% { opacity: 0; filter: blur(4px); transform: scale(0.99) translateY(2px); }
}

@keyframes translateAnimation { 
  0% { transform: translate(0px); }
  50% { transform: translate(250px); }
  100% { transform: translate(0px); }
}

@keyframes animateDown { 
  0% { transform: translateY(0px); }
  50% { transform: translateY(400px); }
  100% { transform: translateY(0px); }
}

@keyframes sparkle-come-in-out { 
  0% { opacity: 0; transform: scale(0); }
  20% { opacity: 1; }
  50% { transform: scale(1); }
  80% { opacity: 1; }
  100% { opacity: 0; transform: scale(0); }
}

@keyframes pop-in { 
  0% { opacity: 0; transform: scale(.8)rotate(var(--rotation,0deg)); }
  100% { opacity: 1; transform: scale(1)rotate(var(--rotation,0deg)); }
}

@keyframes scaleIn { 
  0% { opacity: 0; transform: translate(-50%) scale(0.95); }
  100% { opacity: 1; transform: translate(-50%) scale(1); }
}

@keyframes scaleOut { 
  0% { opacity: 1; transform: translate(-50%) scale(1); }
  100% { opacity: 0; transform: translate(-50%) scale(0.95); }
}

@keyframes swipe-out-left { 
  0% { transform: var(--y) translateX(var(--swipe-amount-x)); opacity: 1; }
  100% { transform: var(--y) translateX(calc(var(--swipe-amount-x) - 100%)); opacity: 0; }
}

@keyframes swipe-out-right { 
  0% { transform: var(--y) translateX(var(--swipe-amount-x)); opacity: 1; }
  100% { transform: var(--y) translateX(calc(var(--swipe-amount-x) + 100%)); opacity: 0; }
}

@keyframes swipe-out-up { 
  0% { transform: var(--y) translateY(var(--swipe-amount-y)); opacity: 1; }
  100% { transform: var(--y) translateY(calc(var(--swipe-amount-y) - 100%)); opacity: 0; }
}

@keyframes swipe-out-down { 
  0% { transform: var(--y) translateY(var(--swipe-amount-y)); opacity: 1; }
  100% { transform: var(--y) translateY(calc(var(--swipe-amount-y) + 100%)); opacity: 0; }
}

@keyframes sonner-fade-in { 
  0% { opacity: 0; transform: scale(0.8); }
  100% { opacity: 1; transform: scale(1); }
}

@keyframes sonner-fade-out { 
  0% { opacity: 1; transform: scale(1); }
  100% { opacity: 0; transform: scale(0.8); }
}
